const ctx = $('Keep Last 7 Days').first().json;
const raw = ($input.first().json && $input.first().json.output) || {};
const clean = (v) => (v === undefined || v === null ? '' : String(v).trim());
const esc = (s) => clean(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const byId = {};
for (const r of (ctx.rows || [])) byId[r.id.toUpperCase()] = r;
const refOk = (id) => !!byId[clean(id).toUpperCase()];
const refRow = (id) => byId[clean(id).toUpperCase()];

// Guard: drop anything citing a row that was not supplied
const matters = (raw.matters || []).filter(m => clean(m.item) && refOk(m.ref_id)).slice(0, 3);
const nextList = (raw.next || []).filter(n => clean(n.action) && refOk(n.ref_id)).slice(0, matters.length);
const actionsById = {};
for (const a of (ctx.actions || [])) actionsById[a.id.toUpperCase()] = a;

let n = ctx.next_action_num;
const newActions = [];
const prepare = (raw.prepare || []).filter(p => clean(p.draft) && refOk(p.ref_id)).slice(0, 2).map(p => {
  const existing = actionsById[clean(p.existing_action_id).toUpperCase()];
  if (existing && existing.status !== 'rejected') {
    return { draft: clean(p.draft), ref_id: clean(p.ref_id), action_id: existing.id, status: existing.status, url: existing.outcome.startsWith('http') ? existing.outcome : '' };
  }
  const id = `A-${n++}`;
  newActions.push({ id, proposed_action: `Draft: ${clean(p.draft)} [${refRow(p.ref_id).id}]`, frequency: 'once', owner: 'the user', approval_status: 'pending' });
  return { draft: clean(p.draft), ref_id: clean(p.ref_id), action_id: id, status: 'pending', url: '' };
});

// ---------- Design tokens (Your Name editorial palette) ----------
const C = { bg: '#F5F5F5', card: '#FFFFFF', line: '#E8E8E8', divider: '#DADADA', red: '#D83A2E', gold: '#F5A623', slate: '#6B7280', ink: '#1F2933' };
const FONT = "-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";
const MONO = "'SFMono-Regular',Menlo,Consolas,monospace";
const CHAT = 'YOUR_N8N_CHAT_URL_HERE';
const SHEET = 'https://docs.google.com/spreadsheets/d/YOUR_GOOGLE_SHEET_ID_HERE/edit#gid=YOUR_MEMORY_TAB_ID_HERE';

const tag = (id) => { const r = refRow(id); return `<span style="display:inline-block;font-family:${MONO};font-size:11px;line-height:16px;color:${C.slate};background:${C.bg};border:1px solid ${C.line};border-radius:4px;padding:1px 6px;white-space:nowrap;">${esc(r.id)} &middot; row ${esc(r.row)}</span>`; };
const chip = (t) => `<span style="display:inline-block;font-size:12px;line-height:18px;font-weight:600;color:#7A4B00;background:#FEF3DC;border:1px solid #F8D48E;border-radius:999px;padding:1px 10px;white-space:nowrap;">&#9201; ${esc(t)}</span>`;
const empty = `<p style="margin:0;padding:14px 16px;font-size:14px;color:${C.slate};font-style:italic;background:${C.bg};border-radius:8px;">No verified item</p>`;
const heading = (num, label, color) => `
  <tr><td style="padding:28px 32px 12px 32px;">
    <table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr>
      <td style="width:4px;background:${color};border-radius:2px;">&nbsp;</td>
      <td style="padding-left:10px;font-family:${FONT};font-size:12px;font-weight:700;letter-spacing:1.4px;text-transform:uppercase;color:${C.ink};">${num}&nbsp;&nbsp;${label}</td>
    </tr></table>
  </td></tr>`;

const mattersHtml = matters.length ? matters.map((m, i) => `
  <tr><td style="padding:0 32px 12px 32px;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="border:1px solid ${C.line};border-radius:10px;">
      <tr>
        <td valign="top" width="44" style="width:44px;min-width:44px;padding:16px 0 16px 16px;">
          <div style="width:28px;height:28px;line-height:28px;text-align:center;border-radius:14px;background:${C.ink};color:#FFFFFF;font-family:${FONT};font-size:13px;font-weight:700;">${i + 1}</div>
        </td>
        <td valign="top" style="padding:16px 16px 16px 8px;font-family:${FONT};">
          <div style="font-size:16px;line-height:22px;font-weight:600;color:${C.ink};">${esc(m.item)}</div>
          <div style="padding-top:8px;">${chip(m.deadline_as_written || 'deadline in note')}&nbsp;&nbsp;${tag(m.ref_id)}</div>
        </td>
      </tr>
    </table>
  </td></tr>`).join('') : `<tr><td style="padding:0 32px 4px 32px;">${empty}</td></tr>`;

const nextHtml = nextList.length ? `
  <tr><td style="padding:0 32px 4px 32px;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
      ${nextList.map((x, i) => `
      <tr>
        <td valign="top" style="width:30px;padding:10px 0;font-family:${FONT};font-size:14px;font-weight:700;color:${C.red};">${i + 1}.</td>
        <td valign="top" style="padding:10px 0;font-family:${FONT};font-size:15px;line-height:21px;color:${C.ink};border-bottom:1px solid ${i === nextList.length - 1 ? '#FFFFFF' : C.line};">${esc(x.action)}<br><span style="display:inline-block;padding-top:4px;">${tag(x.ref_id)}</span></td>
      </tr>`).join('')}
    </table>
  </td></tr>` : `<tr><td style="padding:0 32px 4px 32px;">${empty}</td></tr>`;

const prepareHtml = prepare.length ? prepare.map(p => {
  const action = p.url
    ? `<a href="${esc(p.url)}" style="display:inline-block;font-family:${FONT};font-size:13px;font-weight:600;color:#FFFFFF;background:${C.ink};border-radius:6px;padding:7px 14px;text-decoration:none;">Open draft &rarr;</a>`
    : `<span style="display:inline-block;font-family:${FONT};font-size:13px;color:${C.ink};background:#FFFFFF;border:1px dashed ${C.divider};border-radius:6px;padding:6px 12px;">Reply in chat: <b style="font-family:${MONO};">approve ${esc(p.action_id)}</b></span>`;
  return `
  <tr><td style="padding:0 32px 12px 32px;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#FFFBF2;border:1px solid #F8E3B8;border-left:4px solid ${C.gold};border-radius:8px;">
      <tr><td style="padding:14px 16px;font-family:${FONT};">
        <div style="font-size:11px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:#9A6400;">Draft idea &middot; ${esc(p.action_id)}</div>
        <div style="padding-top:4px;font-size:15px;line-height:21px;color:${C.ink};">${esc(p.draft)}</div>
        <div style="padding-top:10px;">${action}&nbsp;&nbsp;${tag(p.ref_id)}</div>
      </td></tr>
    </table>
  </td></tr>`;
}).join('') : `<tr><td style="padding:0 32px 4px 32px;">${empty}</td></tr>`;

const summary = `${matters.length} commitment${matters.length === 1 ? '' : 's'} &middot; ${prepare.length} draft idea${prepare.length === 1 ? '' : 's'} &middot; ${ctx.count} active note${ctx.count === 1 ? '' : 's'}`;

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><meta name="supported-color-schemes" content="light"><title>Daily Three</title></head>
<body style="margin:0;padding:0;background:${C.bg};">
<div style="display:none;max-height:0;overflow:hidden;opacity:0;">${matters.length ? esc(matters[0].item) : 'No verified commitments today'}</div>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:${C.bg};">
<tr><td align="center" style="padding:24px 12px;">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="max-width:600px;background:${C.card};border:1px solid ${C.line};border-radius:14px;overflow:hidden;">
    <tr><td style="height:5px;background:${C.red};font-size:0;line-height:0;">&nbsp;</td></tr>
    <tr><td style="padding:28px 32px 8px 32px;font-family:${FONT};">
      <div style="font-size:12px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:${C.red};">Daily Three</div>
      <div style="padding-top:6px;font-size:26px;line-height:32px;font-weight:700;color:${C.ink};">${esc(ctx.digest_date)}</div>
      <div style="padding-top:6px;font-size:14px;color:${C.slate};">${summary}</div>
    </td></tr>
    ${heading('01', 'What matters', C.red)}
    ${mattersHtml}
    ${heading('02', 'What is next', C.ink)}
    ${nextHtml}
    ${heading('03', 'What AI can prepare', C.gold)}
    ${prepareHtml}
    <tr><td style="padding:20px 32px 28px 32px;">
      <table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr>
        <td style="padding-right:8px;"><a href="${CHAT}" style="display:inline-block;font-family:${FONT};font-size:14px;font-weight:600;color:#FFFFFF;background:${C.red};border-radius:8px;padding:11px 18px;text-decoration:none;white-space:nowrap;">Open Second Brain chat</a></td>
        <td><a href="${SHEET}" style="display:inline-block;font-family:${FONT};font-size:14px;font-weight:600;color:${C.ink};background:#FFFFFF;border:1px solid ${C.divider};border-radius:8px;padding:10px 18px;text-decoration:none;white-space:nowrap;">Open sheet</a></td>
      </tr></table>
    </td></tr>
    <tr><td style="padding:16px 32px 22px 32px;border-top:1px solid ${C.line};font-family:${FONT};font-size:12px;line-height:18px;color:${C.slate};">
      Built only from active rows in your Second Brain sheet (last 7 days). Drafts are created in Drive only after you approve them. Nothing is ever sent for you.
    </td></tr>
  </table>
</td></tr></table>
</body></html>`;

const plain = [
  `DAILY THREE - ${ctx.digest_date}`, '',
  'WHAT MATTERS', ...(matters.length ? matters.map((m, i) => `${i + 1}. ${m.item} - ${m.deadline_as_written} [${refRow(m.ref_id).id}, row ${refRow(m.ref_id).row}]`) : ['No verified item']), '',
  'WHAT IS NEXT', ...(nextList.length ? nextList.map((x, i) => `${i + 1}. ${x.action} [${refRow(x.ref_id).id}, row ${refRow(x.ref_id).row}]`) : ['No verified item']), '',
  'WHAT AI CAN PREPARE', ...(prepare.length ? prepare.map(p => `- ${p.action_id}: ${p.draft} [${refRow(p.ref_id).id}, row ${refRow(p.ref_id).row}]${p.url ? ' ' + p.url : ' (reply: approve ' + p.action_id + ')'}`) : ['No verified item'])
].join('\n');

return [{ json: {
  subject: `Daily Three - ${ctx.short_date}`,
  html,
  plain,
  word_count: plain.split(/\s+/).filter(Boolean).length,
  dropped: (raw.matters || []).length - matters.length + (raw.prepare || []).length - prepare.length,
  new_actions: newActions
} }];

// Guard: never show a calendar date the sheet does not contain
const ctx = $('Keep Last 7 Days').first().json;
const clean = (v) => (v === undefined || v === null ? '' : String(v).trim());
const due = {};
for (const r of (ctx.rows || [])) due[r.id.toUpperCase()] = clean(r.due_date);
const strip = (text, id) => {
  const keep = due[clean(id).toUpperCase()] || '';
  return clean(text)
    .replace(/[,;]?\s*\(?\s*(due|=|->|i\.e\.)?\s*\d{4}-\d{2}-\d{2}\s*\)?/gi, (m) => (keep && m.includes(keep) ? m : ''))
    .replace(/\s{2,}/g, ' ').trim();
};
const o = $input.first().json.output || {};
const matters = (o.matters || []).map(m => ({ ...m, item: strip(m.item, m.ref_id), deadline_as_written: strip(m.deadline_as_written, m.ref_id) }));
const next = (o.next || []).map(n => ({ ...n, action: strip(n.action, n.ref_id) }));
return [{ json: { output: { ...o, matters, next } } }];

const zone = 'America/Toronto';
const now = DateTime.now().setZone(zone);
const start = now.minus({ days: 7 });
const clean = (v) => (v === undefined || v === null ? '' : String(v).trim());
const parse = (v) => {
  const s = clean(v);
  if (!s) return null;
  let d = DateTime.fromFormat(s, 'yyyy-MM-dd HH:mm', { zone });
  if (!d.isValid) d = DateTime.fromISO(s, { zone });
  return d.isValid ? d.setZone(zone) : null;
};
const memory = $('Read Memory Tab').all().map(i => i.json).filter(r => r && clean(r.id) && clean(r.note));
const actions = $('Read Actions Tab').all().map(i => i.json).filter(r => r && clean(r.id));

const doneLog = memory.filter(r => clean(r.type).toLowerCase() === 'done');
const active = memory
  .filter(r => clean(r.type).toLowerCase() !== 'done')
  .filter(r => !['done', 'archived'].includes(clean(r.status).toLowerCase()))
  .map(r => ({ ...r, _at: parse(r.captured_at) }))
  .filter(r => r._at && r._at >= start && r._at <= now)
  .sort((a, b) => a._at.toMillis() - b._at.toMillis());

const rows = active.map(r => ({
  id: clean(r.id), kind: 'note', row: clean(r.row_number), captured: r._at.toFormat('ccc LLL d'), url: clean(r.file_url),
  person_or_project: clean(r.person_or_project), due_date: clean(r.due_date), note: clean(r.note)
}));

const notesText = active.map(r => [
  `ROW ${clean(r.row_number) || '?'} | id: ${clean(r.id)}`,
  `  captured: ${r._at.toFormat('ccc yyyy-MM-dd HH:mm')}`,
  `  status: ${clean(r.status) || 'new'}`,
  `  person_or_project: ${clean(r.person_or_project) || '(blank)'}`,
  `  due_date: ${clean(r.due_date) || '(blank)'}`,
  `  note: ${clean(r.note)}`
].join('\n')).join('\n\n');

const completedText = doneLog.map(r => `- ${clean(r.note)} (logged ${clean(r.captured_at)}, ${clean(r.id)})`).join('\n');

const openActions = actions.filter(a => !['rejected'].includes(clean(a.approval_status).toLowerCase()));
const actionsText = openActions.map(a => `- ${clean(a.id)} [${clean(a.approval_status) || 'pending'}${clean(a.outcome).startsWith('http') ? ', draft exists' : ''}]: ${clean(a.proposed_action)}`).join('\n');

// ----- Gmail (last 7 days, snippets only) -----
let emails = [];
try { emails = $('Get Recent Emails').all().map(i => i.json).filter(e => e && e.id && !e.error); } catch (e) { emails = []; }
const shortFrom = (f) => clean(f).replace(/<.*?>/g, '').replace(/"/g, '').trim() || clean(f);
const emailRows = emails
  .map(e => ({ ...e, _at: e.internalDate ? DateTime.fromMillis(Number(e.internalDate)).setZone(zone) : null }))
  .filter(e => !e._at || (e._at >= start && e._at <= now))
  .sort((a, b) => (a._at ? a._at.toMillis() : 0) - (b._at ? b._at.toMillis() : 0))
  .slice(-60)
  .map((e, i) => ({ id: `E-${i + 1}`, kind: 'email', row: '', due_date: '', when: e._at ? e._at.toFormat('ccc LLL d') : '', label: `${shortFrom(e.From)}: ${clean(e.Subject) || '(no subject)'}`.slice(0, 70), url: `https://mail.google.com/mail/u/0/#all/${e.id}`, from: shortFrom(e.From), subject: clean(e.Subject), snippet: clean(e.snippet).slice(0, 220) }));
const emailText = emailRows.map(e => `EMAIL ${e.id} | ${e.when} | from: ${e.from} | subject: ${e.subject}\n  preview: ${e.snippet}`).join('\n');

// ----- Calendar (last 7 days) -----
let events = [];
try { events = $('Get Recent Events').all().map(i => i.json).filter(e => e && (e.id || e.summary) && !e.error && e.status !== 'cancelled'); } catch (e) { events = []; }
const evStart = (e) => { const s = (e.start && (e.start.dateTime || e.start.date)) || ''; const d = DateTime.fromISO(s, { zone }); return d.isValid ? d : null; };
const sortedEv = events.map(e => ({ ...e, _at: evStart(e) })).sort((a, b) => (a._at ? a._at.toMillis() : 0) - (b._at ? b._at.toMillis() : 0));
// Collapse repeating routine blocks (same title) into one line, keeping the latest occurrence
const byTitle = new Map();
for (const e of sortedEv) { const t = clean(e.summary) || '(untitled event)'; const g0 = byTitle.get(t) || { ...e, _count: 0 }; byTitle.set(t, { ...e, _count: g0._count + 1 }); }
const eventRows = [...byTitle.values()]
  .sort((a, b) => (a._at ? a._at.toMillis() : 0) - (b._at ? b._at.toMillis() : 0))
  .slice(-30)
  .map((e, i) => ({ id: `C-${i + 1}`, kind: 'event', row: '', due_date: '', repeats: e._count, when: e._at ? e._at.toFormat('ccc LLL d, HH:mm') : '', label: `${clean(e.summary) || '(untitled event)'}`.slice(0, 60), url: clean(e.htmlLink), summary: clean(e.summary) || '(untitled event)', description: clean(e.description).replace(/\s+/g, ' ').slice(0, 200) }));
const eventText = eventRows.map(e => `EVENT ${e.id} | ${e.repeats > 1 ? `repeats ${e.repeats}x this week, last ` : ''}${e.when} | ${e.summary}${e.description ? `\n  details: ${e.description}` : ''}`).join('\n');

const nums = actions.map(a => parseInt(clean(a.id).replace(/^A-/i, ''), 10)).filter(n => !isNaN(n));
const nextActionNum = (nums.length ? Math.max(...nums) : 0) + 1;

return [{ json: {
  count: active.length,
  email_count: emailRows.length,
  event_count: eventRows.length,
  total_sources: active.length + emailRows.length + eventRows.length,
  rows: [...rows, ...emailRows, ...eventRows],
  actions: actions.map(a => ({ id: clean(a.id), status: clean(a.approval_status).toLowerCase() || 'pending', text: clean(a.proposed_action), outcome: clean(a.outcome) })),
  next_action_num: nextActionNum,
  window_start: start.toFormat('ccc LLL d, HH:mm'),
  window_end: now.toFormat('ccc LLL d, HH:mm'),
  today: now.toFormat('cccc yyyy-MM-dd'),
  digest_date: now.toFormat('cccc, LLLL d'),
  short_date: now.toFormat('ccc LLL d, yyyy'),
  notes_text: notesText,
  completed_text: completedText || '(none)',
  actions_text: actionsText || '(none)',
  email_text: emailText || '(none)',
  event_text: eventText || '(none)'
} }];

