const refLabel = (id) => { const r = refRow(id); if (r.kind === 'email') return `${r.id}, email from ${r.from}`; if (r.kind === 'event') return `${r.id}, event ${r.when}`; return `${r.id}, row ${r.row}`; };
const tag = (id) => {
  const r = refRow(id);
  const base = `display:inline-block;font-family:${MONO};font-size:11px;line-height:16px;color:${C.slate};background:${C.bg};border:1px solid ${C.line};border-radius:4px;padding:1px 6px;white-space:nowrap;text-decoration:none;`;
  if (r.kind === 'email') return `<a href="${esc(r.url)}" style="${base}">&#9993; ${esc(r.id)} &middot; ${esc(r.from).slice(0, 28)}</a>`;
  if (r.kind === 'event') return `<a href="${esc(r.url)}" style="${base}">&#128197; ${esc(r.id)} &middot; ${esc(r.when)}</a>`;
  return `<span style="${base}">${esc(r.id)} &middot; row ${esc(r.row)}</span>`;
};
const chip = (t) => `<span style="display:inline-block;font-size:12px;line-height:18px;font-weight:600;color:#7A4B00;background:#FEF3DC;border:1px solid #F8D48E;border-radius:999px;padding:1px 10px;white-space:nowrap;">&#9201; ${esc(t)}</span>`;
const empty = `<p style="margin:0;padding:14px 16px;font-size:14px;color:${C.slate};font-style:italic;background:${C.bg};border-radius:8px;">No verified item</p>`;
const heading = (num, label, color) => `
