    </tr></table>
  </td></tr>`;

const mattersHtml = matters.length ? matters.map((m, i) => `
  <tr><td style="padding:0 32px 12px 32px;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="border:1px solid ${C.line};border-radius:10px;">
      <tr>
        <td valign="top" width="44" style="width:44px;min-width:44px;padding:16px 0 16px 16px;">
          <div style="width:28px;height:28px;line-height:28px;text-align:center;border-radius:14px;background:${C.ink};color:#FFFFFF;font-family:${FONT};font-size:13px;font-weight:700;">${i + 1}</div>
        </td>
        <td valign="top" style="padding:16px 16px 16px 8px;font-family:${FONT};">
          <div style="font-size:16px;line-height:22px;font-weight:600;color:${C.ink};">${esc(m.item)}</div>
          <div style="padding-top:8px;">${chip(m.deadline_as_written || 'deadline in note')}&nbsp;&nbsp;${tag(m.ref_id)}</div>
        </td>
