const plain = [
  `DAILY THREE - ${ctx.digest_date}`, '',
  'WHAT MATTERS', ...(matters.length ? matters.map((m, i) => `${i + 1}. ${m.item} - ${m.deadline_as_written} [${refLabel(m.ref_id)}]`) : ['No verified item']), '',
  'WHAT IS NEXT', ...(nextList.length ? nextList.map((x, i) => `${i + 1}. ${x.action} [${refLabel(x.ref_id)}]`) : ['No verified item']), '',
  'WHAT AI CAN PREPARE', ...(prepare.length ? prepare.map(p => `- ${p.action_id}: ${p.draft} [${refLabel(p.ref_id)}]${p.url ? ' ' + p.url : ' (reply: approve ' + p.action_id + ')'}`) : ['No verified item'])
].join('\n');

return [{ json: {
  subject: `Daily Three - ${ctx.short_date}`,
  html,
  plain,
  word_count: plain.split(/\s+/).filter(Boolean).length,
  dropped: (raw.matters || []).length - matters.length + (raw.prepare || []).length - prepare.length,
  new_actions: newActions
} }];

// Guard: never show a calendar date that is not in the source row, email or event
const ctx = $('Keep Last 7 Days').first().json;
const clean = (v) => (v === undefined || v === null ? '' : String(v).trim());
const srcText = {};
for (const r of (ctx.rows || [])) srcText[r.id.toUpperCase()] = [r.due_date, r.note, r.subject, r.snippet, r.summary, r.description, r.when].map(clean).join(' ');
const strip = (text, id) => {
  const src = srcText[clean(id).toUpperCase()] || '';
  return clean(text)
    .replace(/[,;]?\s*\(?\s*(due|=|->|i\.e\.)?\s*(\d{4}-\d{2}-\d{2})\s*\)?/gi, (m, _p, d) => (src.includes(d) ? m : ''))
    .replace(/\s{2,}/g, ' ').trim();
};
const o = $input.first().json.output || {};
const matters = (o.matters || []).map(m => ({ ...m, item: strip(m.item, m.ref_id), deadline_as_written: strip(m.deadline_as_written, m.ref_id) }));
const next = (o.next || []).map(n => ({ ...n, action: strip(n.action, n.ref_id) }));
return [{ json: { output: { ...o, matters, next } } }];
